CREATE TABLE IF NOT EXISTS inquiries(id TEXT PRIMARY KEY, reference TEXT NOT NULL, request_id TEXT UNIQUE NOT NULL, token_hash TEXT UNIQUE NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL, company TEXT NOT NULL, project_type TEXT NOT NULL, budget TEXT NOT NULL, timeline TEXT NOT NULL, idea TEXT NOT NULL, website TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', proposal TEXT NOT NULL DEFAULT '', proposal_version INTEGER NOT NULL DEFAULT 0, approved_version INTEGER, milestones TEXT NOT NULL DEFAULT '[]', invoice_url TEXT NOT NULL DEFAULT '', payment_note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, inquiry_id TEXT NOT NULL REFERENCES inquiries(id) ON DELETE CASCADE, sender TEXT NOT NULL, text TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS messages_inquiry ON messages(inquiry_id,created_at);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
